using System.ComponentModel;
using System.Text;
using Microsoft.Extensions.AI;

// --- Tool implementations ---

/// <summary>Provides web search and note-taking tools for the research agent.</summary>
static class ResearchTools
{
    private static readonly List<(string Title, string Content)> _notes = [];
    private static readonly HttpClient _http = new();

    [Description("Search the web for information on a given query. Returns a list of result snippets.")]
    public static async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  🔍 Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            // Use Wikipedia API as a publicly available search source
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&srlimit=5&format=json&utf8=1";
            var json = await _http.GetStringAsync(url);

            // Parse results from the JSON response
            var doc = System.Text.Json.JsonDocument.Parse(json);
            var results = doc.RootElement.GetProperty("query").GetProperty("search");
            var sb = new StringBuilder();

            foreach (var item in results.EnumerateArray())
            {
                var title = item.GetProperty("title").GetString();
                var snippet = item.GetProperty("snippet").GetString();
                // Strip HTML tags from snippet
                snippet = System.Text.RegularExpressions.Regex.Replace(snippet ?? "", "<.*?>", "");
                sb.AppendLine($"• {title}: {snippet}");
            }

            return sb.Length > 0 ? sb.ToString() : "No results found.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note with a title and content for later reference.")]
    public static string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("The content of the note")] string content)
    {
        _notes.Add((title, content));

        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        Console.ResetColor();

        return $"Note \"{title}\" saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"[{i + 1}] {_notes[i].Title}");
            sb.AppendLine($"    {_notes[i].Content}");
            sb.AppendLine();
        }
        return sb.ToString();
    }
}

// --- Main program ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
if (string.IsNullOrEmpty(apiKey))
{
    Console.ForegroundColor = ConsoleColor.Red;
    Console.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    Console.ResetColor();
    return 1;
}

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// Build the chat client with automatic function invocation
var openAiClient = new OpenAI.Chat.ChatClient(model, apiKey);
IChatClient client = new ChatClientBuilder(new OpenAIChatClient(openAiClient))
    .UseFunctionInvocation()
    .Build();

// Register tools
var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(ResearchTools.SearchWeb),
        AIFunctionFactory.Create(ResearchTools.SaveNote),
        AIFunctionFactory.Create(ResearchTools.GetNotes),
    ],
};

Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        🔬 AI Research Agent              ║");
Console.WriteLine("║  Enter a topic to research, or 'quit'.   ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.ResetColor();
Console.WriteLine();

List<ChatMessage> history =
[
    new(ChatRole.System,
        """
        You are a research agent. When the user provides a topic:
        1. Search the web multiple times with different queries to gather broad information.
        2. Save key findings as notes using the note-taking tool.
        3. After gathering enough information, retrieve your notes and produce a well-structured
           summary with sections, citing the sources you found.
        Be thorough but concise. Always use the tools available to you.
        """),
];

while (true)
{
    Console.ForegroundColor = ConsoleColor.Yellow;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input) || input.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    history.Add(new(ChatRole.User, input));

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Agent is researching...");
    Console.ResetColor();

    try
    {
        var response = await client.GetResponseAsync(history, chatOptions);

        // Append the assistant response to history for multi-turn conversation
        foreach (var msg in response.Messages)
            history.Add(msg);

        Console.WriteLine();
        Console.ForegroundColor = ConsoleColor.White;
        Console.WriteLine(response.Text);
        Console.ResetColor();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }

    Console.WriteLine();
}

Console.WriteLine("Goodbye!");
return 0;

